import React, { useState } from 'react';
import { useAuthStore } from '../store/authStore';
import { authAPI } from '../utils/api';

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState('test@example.com');
  const [code, setCode] = useState('');
  const [step, setStep] = useState<'email' | 'code'>('email');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [lastCode, setLastCode] = useState('');
  const setAuth = useAuthStore((state) => state.setAuth);

  const handleSendCode = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      await authAPI.sendLoginCode(email);
      setStep('code');
      setError('');
    } catch (err: any) {
      setError(err.response?.data?.error || 'Bir hata oluştu');
    }
    setLoading(false);
  };

  const handleVerifyCode = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!code || code.length !== 6) {
      setError('Lütfen 6 haneli kodu girin');
      return;
    }
    
    setLoading(true);
    setError('');
    try {
      const response = await authAPI.verifyCode(email, code);
      setAuth(response.data.token, response.data.userId, response.data.familyId);
      // Force navigation to dashboard
      window.location.replace('/dashboard');
    } catch (err: any) {
      setError(err.response?.data?.error || 'Kod doğrulama başarısız');
      setCode('');
    }
    setLoading(false);
  };

  const handleCodeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value.replace(/\D/g, '').slice(0, 6);
    setCode(value);
    setError('');
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <div style={styles.header}>
          <h1 style={styles.title}>🏠 Aile İşleri Takip</h1>
          <p style={styles.subtitle}>Ailenizin günlük işlerini kolayca yönetin</p>
        </div>
        
        {step === 'email' ? (
          <form onSubmit={handleSendCode} style={styles.form}>
            <div style={styles.formGroup}>
              <label style={styles.label}>📧 E-posta Adresiniz</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="ornek@email.com"
                style={styles.input}
                required
                autoFocus
              />
            </div>
            <button 
              type="submit" 
              disabled={loading || !email} 
              style={{
                ...styles.button,
                opacity: loading || !email ? 0.6 : 1
              }}
            >
              {loading ? '📤 Gönderiliyor...' : '🔑 Giriş Kodu Gönder'}
            </button>
            
            <div style={styles.helpText}>
              <p>💡 <strong>Test için:</strong> test@example.com kullanın</p>
              <p>📱 Kod e-posta yerine konsola yazdırılacak</p>
            </div>
          </form>
        ) : (
          <form onSubmit={handleVerifyCode} style={styles.form}>
            <div style={styles.codeStep}>
              <div style={styles.successMessage}>
                ✅ Kod gönderildi: <strong>{email}</strong>
              </div>
              
              <div style={styles.formGroup}>
                <label style={styles.label}>🔢 6 Haneli Giriş Kodu</label>
                <input
                  type="text"
                  value={code}
                  onChange={handleCodeChange}
                  placeholder="000000"
                  maxLength={6}
                  style={{
                    ...styles.input,
                    ...styles.codeInput,
                    textAlign: 'center' as const,
                    fontSize: '24px',
                    letterSpacing: '8px'
                  }}
                  autoFocus
                  autoComplete="off"
                />
                <div style={styles.codeHint}>
                  Konsol çıktısından kodu kopyalayın
                </div>
              </div>
              
              <button 
                type="submit" 
                disabled={loading || code.length !== 6} 
                style={{
                  ...styles.button,
                  opacity: loading || code.length !== 6 ? 0.6 : 1
                }}
              >
                {loading ? '🔄 Doğrulanıyor...' : '✅ Giriş Yap'}
              </button>
              
              <button 
                type="button"
                onClick={() => {
                  setStep('email');
                  setCode('');
                  setError('');
                }} 
                style={styles.secondaryButton}
              >
                ← E-posta Değiştir
              </button>
            </div>
          </form>
        )}

        {error && (
          <div style={styles.error}>
            ❌ {error}
          </div>
        )}
        
        <div style={styles.footer}>
          <p>🔒 Güvenli giriş sistemi</p>
          <p>👨‍👩‍👧‍👦 Tüm aile için tasarlandı</p>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    padding: '20px',
  },
  card: {
    backgroundColor: 'white',
    padding: '40px',
    borderRadius: '16px',
    boxShadow: '0 20px 40px rgba(0,0,0,0.1)',
    width: '100%',
    maxWidth: '450px',
    animation: 'slideUp 0.6s ease-out',
  },
  header: {
    textAlign: 'center' as const,
    marginBottom: '32px',
  },
  title: {
    color: '#2c3e50',
    marginBottom: '8px',
    fontSize: '28px',
    fontWeight: '700',
  },
  subtitle: {
    color: '#7f8c8d',
    fontSize: '16px',
    margin: 0,
  },
  form: {
    width: '100%',
  },
  formGroup: {
    marginBottom: '24px',
  },
  label: {
    display: 'block',
    marginBottom: '8px',
    color: '#2c3e50',
    fontWeight: '600',
    fontSize: '14px',
  },
  input: {
    width: '100%',
    padding: '16px',
    border: '2px solid #e9ecef',
    borderRadius: '8px',
    fontSize: '16px',
    boxSizing: 'border-box' as const,
    transition: 'border-color 0.3s ease',
    outline: 'none',
  },
  codeInput: {
    fontFamily: 'monospace',
    fontWeight: 'bold' as const,
  },
  button: {
    width: '100%',
    padding: '16px',
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    fontSize: '16px',
    cursor: 'pointer',
    fontWeight: '600',
    transition: 'all 0.3s ease',
    marginBottom: '12px',
  },
  secondaryButton: {
    width: '100%',
    padding: '12px',
    backgroundColor: 'transparent',
    color: '#6c757d',
    border: '2px solid #e9ecef',
    borderRadius: '8px',
    fontSize: '14px',
    cursor: 'pointer',
    fontWeight: '500',
    transition: 'all 0.3s ease',
  },
  error: {
    color: '#dc3545',
    marginTop: '16px',
    padding: '12px',
    backgroundColor: '#f8d7da',
    borderRadius: '8px',
    fontSize: '14px',
    fontWeight: '500',
  },
  helpText: {
    marginTop: '20px',
    padding: '16px',
    backgroundColor: '#e7f3ff',
    borderRadius: '8px',
    fontSize: '14px',
    color: '#0066cc',
  },
  codeStep: {
    textAlign: 'center' as const,
  },
  successMessage: {
    backgroundColor: '#d4edda',
    color: '#155724',
    padding: '12px',
    borderRadius: '8px',
    marginBottom: '24px',
    fontSize: '14px',
    fontWeight: '500',
  },
  codeHint: {
    fontSize: '12px',
    color: '#6c757d',
    marginTop: '8px',
    fontStyle: 'italic',
  },
  footer: {
    textAlign: 'center' as const,
    marginTop: '32px',
    paddingTop: '20px',
    borderTop: '1px solid #e9ecef',
    fontSize: '12px',
    color: '#95a5a6',
  },
};

export default LoginPage;
